using System;using System.IO;using System.Collections.Generic;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Effects;using Microsoft.Win32;
public sealed class PreviewPreferences {
 public bool closeToTray=true,minimizeToTray=false,startMinimized=false;public int historyDays=30,historyLimitMB=256;public string density="comfortable",iconThemeId="night";public double scale=1.0;
 public static PreviewPreferences Load(){try{var value=ArchiveStore.Json().Deserialize<PreviewPreferences>(File.ReadAllText(Path.Combine(WorkbenchHost.DataRoot,"preferences.json")))??new PreviewPreferences();value.iconThemeId=BrandIcons.Normalize(value.iconThemeId);return value;}catch{return new PreviewPreferences();}}
 public void Save(){string path=Path.Combine(WorkbenchHost.DataRoot,"preferences.json"),temp=path+".tmp";File.WriteAllText(temp,ArchiveStore.Json().Serialize(this));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
}
public sealed class PreviewDesktop:IDisposable {
 readonly WorkbenchWindow owner;readonly System.Windows.Forms.NotifyIcon icon;readonly Action<string> showPage;readonly Action quit;Window flyout;string theme="graphite",trayKey="";readonly string iconId;System.Drawing.Icon currentIcon;
 public PreviewDesktop(WorkbenchWindow window,Action<string> show,Action exit,string selectedIcon){iconId=BrandIcons.Normalize(selectedIcon);owner=window;showPage=show;quit=exit;icon=new System.Windows.Forms.NotifyIcon{Icon=(currentIcon=BrandIcons.Tray(iconId,"neutral")),Text="AsterHub Preview · 持续记录",Visible=true};icon.DoubleClick+=delegate{owner.Dispatcher.BeginInvoke(new Action(Restore));};icon.MouseUp+=delegate(object s,System.Windows.Forms.MouseEventArgs e){if(e.Button==System.Windows.Forms.MouseButtons.Right)owner.Dispatcher.BeginInvoke(new Action(ShowMenu));};}
 public void RefreshStatus(string state){string key=state+"/"+TaskbarLight();if(key==trayKey)return;var next=BrandIcons.Tray(iconId,state);var old=currentIcon;icon.Icon=next;currentIcon=next;trayKey=key;if(old!=null)old.Dispose();}
 static bool TaskbarLight(){try{using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize")){return key!=null&&Convert.ToInt32(key.GetValue("SystemUsesLightTheme",0))!=0;}}catch{return false;}}
 public bool Visible{get{return icon.Visible;}}public bool MenuOpen{get{return flyout!=null&&flyout.IsVisible;}}
 public void Restore(){CloseMenu();owner.Show();if(owner.WindowState==WindowState.Minimized)owner.WindowState=WindowState.Normal;owner.Activate();}
 public void ApplyTheme(string value){theme=value;CloseMenu();}
 public void CloseMenu(){if(flyout!=null){var w=flyout;flyout=null;w.Close();}}
 public void ShowMenu(){CloseMenu();bool light=theme=="light";var bg=new SolidColorBrush((Color)ColorConverter.ConvertFromString(light?"#FFFFFF":theme=="forest"?"#202E27":theme=="ocean"?"#202D3C":theme=="slate"?"#222631":"#222724"));var fg=new SolidColorBrush((Color)ColorConverter.ConvertFromString(light?"#29354A":theme=="graphite"?"#E5EAE5":"#E9EDF5"));var muted=new SolidColorBrush((Color)ColorConverter.ConvertFromString(light?"#53647B":theme=="graphite"?"#A0AAA2":"#B0B9CB"));var line=new SolidColorBrush((Color)ColorConverter.ConvertFromString(light?"#CCD4E3":theme=="graphite"?"#343C36":"#3A4354"));var stack=new StackPanel();stack.Children.Add(new TextBlock{Text="AsterHub",FontSize=18,FontWeight=FontWeights.SemiBold,Foreground=fg,Margin=new Thickness(14,10,14,1)});stack.Children.Add(new TextBlock{Text="设备监控 · 持续记录",FontSize=14,Foreground=muted,Margin=new Thickness(14,0,14,12)});
  Add(stack,"\uE80F","打开主窗口",()=>Restore(),fg,bg,light);Add(stack,"\uE713","偏好设置",()=>{Restore();showPage("preferences");},fg,bg,light);Add(stack,"\uE946","关于 AsterHub",()=>{Restore();showPage("about");},fg,bg,light);stack.Children.Add(new Border{Height=1,Background=line,Margin=new Thickness(12,6,12,6)});Add(stack,"\uE8AC","退出 AsterHub",quit,fg,bg,light);
  var border=new Border{CornerRadius=new CornerRadius(14),Background=bg,BorderBrush=line,BorderThickness=new Thickness(1),Padding=new Thickness(6),Child=stack,Effect=new DropShadowEffect{BlurRadius=18,ShadowDepth=3,Opacity=.2}};var w=new Window{WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false,ShowActivated=true,Topmost=true,SizeToContent=SizeToContent.WidthAndHeight,Content=new Border{Margin=new Thickness(12),Child=border},Width=290,Left=-18000,Top=-18000};flyout=w;w.Deactivated+=delegate{if(w.IsVisible)w.Close();};w.Closed+=delegate{if(flyout==w)flyout=null;};w.PreviewKeyDown+=delegate(object s,KeyEventArgs e){if(e.Key==Key.Escape){e.Handled=true;CloseMenu();}};w.Show();w.UpdateLayout();var cursor=System.Windows.Forms.Cursor.Position;var point=w.PointFromScreen(new Point(cursor.X,cursor.Y));var screen=w.PointToScreen(new Point(0,0));var src=PresentationSource.FromVisual(w);var transform=src.CompositionTarget.TransformFromDevice;var p=transform.Transform(new Point(cursor.X,cursor.Y));var work=SystemParameters.WorkArea;w.Left=Math.Max(work.Left,Math.Min(work.Right-w.ActualWidth,p.X-w.ActualWidth+20));w.Top=Math.Max(work.Top,Math.Min(work.Bottom-w.ActualHeight,p.Y-w.ActualHeight+12));w.Activate();}
 void Add(StackPanel stack,string glyph,string text,Action action,Brush fg,Brush bg,bool light){var row=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};row.Children.Add(new TextBlock{Text=glyph,FontFamily=new FontFamily("Segoe MDL2 Assets"),FontSize=16,Width=30,VerticalAlignment=VerticalAlignment.Center});row.Children.Add(new TextBlock{Text=text,FontSize=14,VerticalAlignment=VerticalAlignment.Center});var button=new Button{Content=row,Height=40,Margin=new Thickness(1),Padding=new Thickness(12,0,12,0),Background=bg,Foreground=fg,BorderThickness=new Thickness(0),HorizontalContentAlignment=HorizontalAlignment.Stretch,Cursor=Cursors.Hand};var template=new ControlTemplate(typeof(Button));var b=new FrameworkElementFactory(typeof(Border));b.SetValue(Border.CornerRadiusProperty,new CornerRadius(9));b.SetBinding(Border.BackgroundProperty,new System.Windows.Data.Binding("Background"){RelativeSource=System.Windows.Data.RelativeSource.TemplatedParent});var cp=new FrameworkElementFactory(typeof(ContentPresenter));cp.SetValue(FrameworkElement.MarginProperty,new Thickness(12,0,12,0));cp.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);b.AppendChild(cp);template.VisualTree=b;button.Template=template;button.MouseEnter+=delegate{button.Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(light?"#E4E9E1":"#303A33"));};button.MouseLeave+=delegate{button.Background=bg;};button.Click+=delegate{CloseMenu();action();};System.Windows.Automation.AutomationProperties.SetName(button,text);stack.Children.Add(button);}
 public static bool StartupEnabled(){using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){return key!=null&&Convert.ToString(key.GetValue("AsterHubPreview"))==StartupCommand();}}
 static string StartupCommand(){return "\""+Assembly.GetExecutingAssembly().Location+"\" --background";}
 public static void SetStartup(bool value){if(WorkbenchHost.SmokeRoot!=null)throw new InvalidOperationException("隔离测试不修改开机启动项");using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){if(value)key.SetValue("AsterHubPreview",StartupCommand());else if(Convert.ToString(key.GetValue("AsterHubPreview"))==StartupCommand())key.DeleteValue("AsterHubPreview",false);}}
 public void Dispose(){CloseMenu();icon.Visible=false;icon.Dispose();if(currentIcon!=null){currentIcon.Dispose();currentIcon=null;}}
}
